/* Nelson Textbook data chunk 01/07; generated only from absi/Nelson.zip. */
window.__SHB_NELSON_QUESTIONS__=(window.__SHB_NELSON_QUESTIONS__||[]).concat([{"id":"NEL-CNSACCEPTE-003","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Contraindications to performing a lumbar puncture include the following ExCEPT","o":["suspected mass lesion of the brain","suspected mass lesion of the spinal cord","symptoms and signs of impending cerebral herniation","skin infection at the site of the lumbar puncture","thrombocytopenia with a platelet count <50 x 10/L"],"k":4,"ex":"A lumbar puncture is contraindicated by suspected brain or spinal cord mass, signs of impending herniation, local skin infection and a bleeding disorder. Nelson's explanation puts the platelet threshold at below 20 x 10^9/L, so a count below 50 x 10^9/L is not an absolute contraindication.","more":"Options:\n- A. suspected brain mass — contraindication (herniation risk).\n\n- B. suspected spinal cord mass — contraindication.\n- C. impending herniation — contraindication.\n- D. skin infection at the site — contraindication.\n- E. **Correct (source key):** the source threshold is below 20, not below 50.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q3, PDF p.475; answer on PDF p.495","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":3,"f":false},{"id":"NEL-CNSACCEPTE-004","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"An elevated polymorphonuclear (PMN) cells count in cerebrospinal fluid (CSF) suggests","o":["tuberculous meningitis","early phase of aseptic meningitis","fungal meningitis","demyelinating diseases","brain or spinal cord tumor"],"k":1,"ex":"Normal CSF contains up to 5 cells/mm3. Polymorphonuclear cells are always abnormal in a child; an elevated PMN count suggests bacterial meningitis or the early phase of aseptic meningitis.","more":"Options:\n- A. tuberculous meningitis — lymphocytic.\n\n- B. **Correct (source key).**\n- C. fungal meningitis — lymphocytic.\n- D. demyelinating diseases — lymphocytic.\n- E. brain or spinal cord tumor — lymphocytic (label lost in OCR).\n\nHigh-yield:\nEarly tuberculous or aseptic meningitis can show PMNs briefly, which is why the key says \"early phase\".","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q4, PDF p.475; answer on PDF p.495","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":4,"f":false},{"id":"NEL-CNSACCEPTE-012","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Differential Diagnosis","q":"Causes of communicating hydrocephalus include","o":["achondroplasia","aqueductal stenosis","Chiari malformation","Dandy-Walker malformation","Klippel-Feil syndrome"],"k":0,"ex":"Achondroplasia is a cause of communicating hydrocephalus (narrow foramen magnum and jugular foramina impair venous drainage and CSF absorption). Aqueductal stenosis, Chiari malformation, Dandy-Walker malformation and Klippel-Feil syndrome are causes of non-communicating (obstructive) hydrocephalus per the source.","more":"Options:\n- A. **Correct (source key).**\n\n- B. aqueductal stenosis — obstructive.\n- C. Chiari malformation — obstructive.\n- D. Dandy-Walker malformation — obstructive.\n- E. Klippel-Feil syndrome — obstructive (as listed by the source).","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q12, PDF p.477; answer on PDF p.496","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":12,"f":false},{"id":"NEL-CNSACCEPTE-013","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Differential Diagnosis","q":"Nonobstructive or communicating hydrocephalus may follow the following conditions EXCEPT","o":["a subarachnoid hemorrhage","pneumococcal meningitis","tuberculous meningitis","leukemic infiltrates","a vein of Galen malformation"],"k":4,"ex":"Communicating hydrocephalus follows blockage of CSF absorption at the arachnoid villi or basal cisterns: subarachnoid hemorrhage, bacterial and tuberculous meningitis and leukemic infiltrates. A vein of Galen malformation can enlarge and, because of its midline position, obstruct CSF flow, so it causes obstructive hydrocephalus.","more":"Options:\n- A. subarachnoid hemorrhage — communicating.\n\n- B. pneumococcal meningitis — communicating.\n- C. tuberculous meningitis — communicating.\n- D. leukemic infiltrates — communicating.\n- E. **Correct (source key).**","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q13, PDF p.477; answer on PDF p.496","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":13,"f":false},{"id":"NEL-CNSACCEPTE-015","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Trigoncephaly is a skull deformity that is a direct result of premature fusion of the following","o":["sagittal suture","coronal suture","lambdoid suture","metopic suture","multiple sutures"],"k":3,"ex":"Trigonocephaly (triangular forehead) results from premature fusion of the metopic suture. Sagittal fusion gives scaphocephaly, coronal fusion gives brachycephaly (bilateral) or anterior plagiocephaly (unilateral), lambdoid fusion gives posterior plagiocephaly, and multiple sutures give oxycephaly.","more":"Options:\n- A. sagittal — scaphocephaly.\n\n- B. coronal — brachycephaly/anterior plagiocephaly.\n- C. lambdoid — posterior plagiocephaly.\n- D. **Correct (source key).**\n- E. multiple sutures — oxycephaly.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q15, PDF p.477; answer on PDF p.496","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":15,"f":false},{"id":"NEL-CNSACCEPTE-016","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Crouzon syndrome is characterized by the following ExCEPT","o":["an autosomal dominant inheritance","brachycephaly","ocular proptosis","hypoplasia of the maxilla","syndactyly"],"k":4,"ex":"Crouzon syndrome is autosomal dominant craniosynostosis with brachycephaly, ocular proptosis and maxillary hypoplasia. Syndactyly belongs to Apert syndrome (source explanation).","more":"Options:\n- A. autosomal dominant — true.\n\n- B. brachycephaly — true.\n- C. ocular proptosis — true.\n- D. hypoplasia of the maxilla — true (label lost in OCR).\n- E. **Correct (source key):** syndactyly is Apert.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q16, PDF pp.477-478; answer on PDF p.496","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":16,"f":false},{"id":"NEL-CNSACCEPTE-018","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Prognosis","q":"There are several predictors of epilepsy after febrile seizures, the highest percent of risk factor for subsequent epilepsy after febrile seizure is","o":["complex febrile seizure, any type","fever <1 hr before febrile seizure","recurrent febrile seizures","focal complex febrile seizure family history of epilepsy"],"k":3,"ex":"Among the options, focal complex febrile seizure carries the highest risk of later epilepsy (29%). Source figures: simple febrile seizure 1%, recurrent febrile seizures 4%, complex 6%, fever under 1 hour before the seizure 11%, family history of epilepsy 18%, focal complex 29%, neurodevelopmental abnormalities 33%.","more":"Options:\n- A. complex febrile seizure, any type — 6%.\n\n- B. fever under 1 hour before the seizure — 11%.\n- C. recurrent febrile seizures — 4%.\n- D. **Correct (source key):** 29%.\n- E. family history of epilepsy — 18%.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q18, PDF p.478; answer on PDF p.496","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":18,"f":false},{"id":"NEL-CNSACCEPTE-021","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"Absence seizures are MOsT often initially treated with","o":["ethosuximide","valproate","lamotrigine","acetazolamide","clonazepam"],"k":0,"ex":"Absence seizures are most often treated first with ethosuximide, which is as effective as valproate and less toxic, and more effective than lamotrigine (source explanation).","more":"Options:\n- A. **Correct (source key).**\n\n- B. valproate — equally effective but more toxic; preferred when generalized tonic-clonic seizures coexist.\n- C. lamotrigine — less effective.\n- D. acetazolamide — not a first-line drug.\n- E. clonazepam — not first-line.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q21, PDF pp.478-479; answer on PDF p.496","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":21,"f":false},{"id":"NEL-CNSACCEPTE-022","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"Benign myoclonic epilepsies are often best treated with","o":["clonazepam","lamotrigine","topiramate","valproate","benzodiazepines"],"k":3,"ex":"Benign myoclonic epilepsies are often best treated with valproate, especially with associated generalized tonic-clonic and absence seizures. Benzodiazepines, clonazepam, lamotrigine and topiramate are alternatives.","more":"Options:\n- A. clonazepam — alternative.\n\n- B. lamotrigine — alternative.\n- C. topiramate — alternative.\n- D. **Correct (source key).**\n- E. benzodiazepines — alternative (label lost in OCR).\n\nHigh-yield:\nValproate is teratogenic, which matters for adolescent girls.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q22, PDF p.479; answer on PDF p.496","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":22,"f":false},{"id":"NEL-CNSACCEPTE-023","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pharmacology","q":"Gingival hyperplasia, coarsening of the facies, hirsutism, and cerebellovestibular symptoms (nystagmus and ataxia) are adverse effects of","o":["carbamazepine","lamotrigine","phenytoin","valproic acid","succinimides"],"k":2,"ex":"Chronic phenytoin causes gingival hyperplasia, coarsening of the facies, hirsutism and cerebellovestibular toxicity (nystagmus, ataxia).","more":"Options:\n- A. carbamazepine — hyponatremia, rash, dizziness.\n\n- B. lamotrigine — rash (Stevens-Johnson risk).\n- C. **Correct (source key).**\n- D. valproic acid — weight gain, tremor, alopecia, hepatotoxicity.\n- E. succinimides — GI upset, rash.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q23, PDF p.479; answer on PDF p.496","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":23,"f":false},{"id":"NEL-CNSACCEPTE-025","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Management","q":".Epilepsy surgery is often used to treat refractory epilepsy of a number of etiologies including the following EXCEPT","o":["cortical dysplasia","tuberous sclerosis","polymicrogyria","degenerative problems","Sturge-Weber syndrome"],"k":3,"ex":"Epilepsy surgery is used for refractory epilepsy from focal or hemispheric causes (cortical dysplasia, tuberous sclerosis, polymicrogyria, hypothalamic hamartoma, Sturge-Weber syndrome, Rasmussen encephalitis). Intractable epilepsy from metabolic or degenerative disease is not a candidate for resective surgery, because the process is diffuse.","more":"Options:\n- A. cortical dysplasia — candidate.\n\n- B. tuberous sclerosis — candidate.\n- C. polymicrogyria — candidate.\n- D. **Correct (source key).**\n- E. Sturge-Weber syndrome — candidate.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q25, PDF p.479; answer on PDF p.496","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":25,"f":false},{"id":"NEL-CNSACCEPTE-026","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pathophysiology","q":"The MOsT common cause of neonatal seizures is","o":["vascular events","intracranial infections","brain malformations","hypoxic-Ischemic encephalopathy","metabolic disturbances"],"k":3,"ex":"Hypoxic-ischemic encephalopathy is the commonest cause of neonatal seizures (50-60%), with onset within about 12 hours of birth. Vascular events, infection, malformations and metabolic disturbances are less common.","more":"Options:\n- A. vascular events — less common.\n\n- B. intracranial infections — less common.\n- C. brain malformations — 5-10%.\n- D. **Correct (source key).**\n- E. metabolic disturbances — less common.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q26, PDF p.479; answer on PDF p.497","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":26,"f":false},{"id":"NEL-CNSACCEPTE-029","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Tension-type headaches (TTH) are characterized by the following EXCEPT","o":["diffuse in location","not affected by activity","throbbing quality","mild to moderate in severity","less frequently associated with nausea and photophobia"],"k":2,"ex":"Tension-type headache is diffuse, mild to moderate, nonthrobbing (a constant pressure), not worsened by activity, and less often accompanied by nausea and photophobia. A throbbing quality points to migraine.","more":"Options:\n- A. diffuse in location — true.\n\n- B. not affected by activity — true.\n- C. **Correct (source key).**\n- D. mild to moderate — true.\n- E. less nausea and photophobia — true.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q29, PDF p.480; answer on PDF p.497","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":29,"f":false},{"id":"NEL-CNSACCEPTE-030","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Complications","q":"The following are complications of neurofibromatosis (type 1) NF-1 EXCEPT","o":["learning disability","cataracts","seizures",".precocious puberty","scoliosis"],"k":1,"ex":"NF-1 complications include learning disability, seizures, precocious puberty and scoliosis. Cataracts (60-81%) belong to NF-2, not NF-1.","more":"Options:\n- A. learning disability — NF-1.\n\n- B. **Correct (source key):** cataracts occur in NF-2.\n- C. seizures — NF-1.\n- D. precocious puberty — NF-1 (label lost in OCR).\n- E. scoliosis — NF-1.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q30, PDF p.480; answer on PDF p.497","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":30,"f":false},{"id":"NEL-CNSACCEPTE-035","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"The current antiepileptic drug (AEDs) of choice for primary generalized tonic-clonic seizures in children is","o":["phenytoin","carbamazepine","phenobarbital","valproate","topiramate"],"k":3,"ex":"Valproate (together with lamotrigine) has emerged as the current drug of choice for primary generalized tonic-clonic seizures in children, on the basis of efficacy and tolerability (source explanation).","more":"Options:\n- A. phenytoin — effective but not preferred (side effects).\n\n- B. carbamazepine — effective, but can worsen absence/myoclonic seizures.\n- C. phenobarbital — effective but sedating.\n- D. **Correct (source key).**\n- E. topiramate — effective, not the first choice.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q35, PDF p.481; answer on PDF p.497","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":35,"f":false},{"id":"NEL-CNSACCEPTE-037","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The following are manifestations of increased intracranial pressure in an infant EXCEPT","o":["increasing head circumference","bulging fontanel","failure to thrive","persistent vomiting","setting sun sign"],"k":3,"ex":"Raised intracranial pressure in an infant causes increasing head circumference, bulging fontanel, failure to thrive, suture separation, setting-sun sign and shrill cry. Persistent vomiting is listed by Nelson among the signs in the older child.","more":"Options:\n- A. increasing head circumference — infant sign.\n\n- B. bulging fontanel — infant sign.\n- C. failure to thrive — infant sign.\n- D. **Correct (source key).**\n- E. setting-sun sign — infant sign.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q37, PDF p.481; answer on PDF p.497","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":37,"f":false},{"id":"NEL-CNSACCEPTE-038","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Characteristic features of pseudotumor cerebri include the following ExCEPT","o":["headache","stiff neck","papilledema","fatigue","abnormal CSF profile"],"k":4,"ex":"Pseudotumor cerebri (idiopathic intracranial hypertension) gives headache, papilledema and fatigue, with a normal CSF profile apart from an elevated opening pressure. An abnormal CSF profile is therefore the exception.","more":"Options:\n- A. headache — characteristic.\n\n- B. stiff neck — may accompany headache (neck pain).\n- C. papilledema — characteristic.\n- D. fatigue — characteristic.\n- E. **Correct (source key).**","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q38, PDF pp.481-482; answer on PDF p.497","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":38,"f":false},{"id":"NEL-CNSACCEPTE-041","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other (Development)","q":"A 9-month-old infant can do all the following ExCEPT","o":["pulls to stand",". pincer grasp","plays pat-a-cake","imitates sounds","comes when called"],"k":4,"ex":"Walking with one hand held, releasing an object on command, coming when called and 1-2 meaningful words are 12-month milestones. A 9-month-old pulls to stand, has a pincer grasp (immature), plays pat-a-cake and imitates sounds, but does not yet come when called.","more":"Options:\n- A. pulls to stand — 9 months.\n\n- B. pincer grasp — 9 months (label lost in OCR).\n- C. plays pat-a-cake — 9 months.\n- D. imitates sounds — 9 months.\n- E. **Correct (source key).**","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q41, PDF p.482; answer on PDF p.498","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":41,"f":false},{"id":"NEL-CNSACCEPTE-044","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Craniosynostosis is defined as premature closure of the cranial sutures. Of the following, the MosT common form of craniosynostosis is","o":["frontal plagiocephaly","occipital plagiocephaly","scaphocephaly","trigonocephaly","turricephaly"],"k":2,"ex":"Premature closure of the sagittal suture gives a long narrow skull (scaphocephaly), the most common craniosynostosis.","more":"Options:\n- A. frontal plagiocephaly — unilateral coronal fusion.\n\n- B. occipital plagiocephaly — lambdoid fusion, rare.\n- C. **Correct (source key).**\n- D. trigonocephaly — metopic fusion.\n- E. turricephaly — multiple sutures.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q44, PDF pp.482-483; answer on PDF p.498","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":44,"f":false},{"id":"NEL-CNSACCEPTE-045","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pathophysiology","q":"The following are risk factors for deformational plagiocephaly ExCEPT","o":["female sex","firstborn child","congenital torticollis","developmental delay","exclusive bottle feeding"],"k":0,"ex":"Male sex, not female sex, is the risk factor for deformational plagiocephaly. Firstborn status, congenital torticollis, developmental delay and positioning preference with bottle feeding also contribute.","more":"Options:\n- A. **Correct (source key):** female sex is not a risk factor.\n\n- B. firstborn child — risk factor.\n- C. congenital torticollis — risk factor.\n- D. developmental delay — risk factor.\n- E. exclusive bottle feeding — risk factor.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q45, PDF p.483; answer on PDF p.498","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":45,"f":false},{"id":"NEL-CNSACCEPTE-046","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Prognosis","q":"Major risk factors for recurrence of febrile seizure include","o":["fever 38-39°c","family history of febrile seizures","family history of epilepsy","complex febrile seizure","lower serum sodium at time of presentation"],"k":0,"ex":"Major risk factors for recurrence of febrile seizure are age under 1 year, duration of fever under 24 hours and fever of 38-39 °C. Minor ones are a family history of febrile seizures or epilepsy, complex febrile seizure, daycare, male gender and low serum sodium.","more":"Options:\n- A. **Correct (source key).**\n\n- B. family history of febrile seizures — minor.\n- C. family history of epilepsy — minor (label lost in OCR).\n- D. complex febrile seizure — minor.\n- E. lower serum sodium — minor.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q46, PDF p.483; answer on PDF p.498","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":46,"f":false},{"id":"NEL-CNSACCEPTE-047","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Prognosis","q":"In patients with febrile seizures, one of the following risk factors has the highest risk for subsequent epilepsy","o":["recurrent febrile seizures","fever <1 hr before febrile seizure","neurodevelopmental abnormalities","family history of epilepsy","complex febrile seizures"],"k":2,"ex":"Among the options, neurodevelopmental abnormalities carry the highest risk for later epilepsy (33%). Other options: recurrent febrile seizures 4%, fever under 1 hour 11%, family history of epilepsy 18%, complex febrile seizures 6% (focal complex 29%).","more":"Options:\n- A. recurrent febrile seizures — 4%.\n\n- B. fever under 1 hour before the seizure — 11%.\n- C. **Correct (source key):** 33%.\n- D. family history of epilepsy — 18%.\n- E. complex febrile seizures — 6%.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q47, PDF p.483; answer on PDF p.498","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":47,"f":false},{"id":"NEL-CNSACCEPTE-052","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"Drug therapy should be based on the type of seizure and the epilepsy syndrome as well as on other individual factors. Of the following, the drug of first choice for focal seizures and epilepsies is","o":["carbamazepine","ethosuximide","valproate","lamotrigine","clobazam"],"k":0,"ex":"For focal seizures the drugs of first choice are carbamazepine and oxcarbazepine. Ethosuximide is for absence, valproate (and lamotrigine) for juvenile myoclonic epilepsy, and clobazam, valproate, topiramate and lamotrigine for Lennox-Gastaut.","more":"Options:\n- A. **Correct (source key).**\n\n- B. ethosuximide — absence seizures.\n- C. valproate — generalized epilepsies.\n- D. lamotrigine — alternative.\n- E. clobazam — Lennox-Gastaut add-on.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q52, PDF p.484; answer on PDF p.499","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":52,"f":false},{"id":"NEL-CNSACCEPTE-053","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pharmacology","q":"Weight gain and alopecia are side effects of the following antiepileptic drugs AEDs","o":["primidone","valproic acid","oxcarbazepine","lamotrigine","acetazolamide"],"k":1,"ex":"Valproic acid causes weight gain, hyperammonemia, tremor, alopecia and menstrual irregularities; serious effects are hepatic and pancreatic toxicity.","more":"Options:\n- A. primidone — sedation.\n\n- B. **Correct (source key).**\n- C. oxcarbazepine — hyponatremia.\n- D. lamotrigine — rash.\n- E. acetazolamide — paresthesias, metabolic acidosis.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q53, PDF p.484; answer on PDF p.499","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":53,"f":false},{"id":"NEL-CNSACCEPTE-068","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Migraine is the most frequent type of recurrent headache that is brought to the attention of parents and primary care providers, but it remains under recognized and undertreated, particularly in children. Migraine is characterized by all the following ExcEPT","o":["episodic attacks","moderate to severe in intensity","focal in location on the head","constant quality","may be associated with nausea and vomiting"],"k":3,"ex":"Migraine consists of episodic attacks that are moderate to severe, focal on the head (often bilateral bifrontal in children), throbbing in quality and may be accompanied by nausea, vomiting, photophobia and phonophobia. A constant, pressure-like quality is characteristic of tension-type headache.","more":"Options:\n- A. episodic attacks — characteristic.\n\n- B. moderate to severe intensity — characteristic.\n- C. focal in location — characteristic.\n- D. **Correct (source key).**\n- E. nausea and vomiting — characteristic.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q68, PDF p.487; answer on PDF p.500","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":68,"f":false},{"id":"NEL-CNSACCEPTE-070","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"The following are indications for neuroimaging in a child with a headache ExCEPT","o":["abnormal neurologic examination","headache worst on first awakening","brief cough headache","frontal headache","migrainous headache in the child with no family history of migraine"],"k":3,"ex":"Neuroimaging is indicated for an abnormal neurologic examination, headache waking the child or present on first awakening, brief headache only with cough or bending, migraine with no family history, and (per the source) occipital headache. A frontal headache is not an indication.","more":"Options:\n- A. abnormal neurologic examination — indication.\n\n- B. worst on first awakening — indication.\n- C. brief cough headache — indication.\n- D. **Correct (source key):** frontal headache is not an indication; the source names occipital location.\n- E. migrainous headache without family history — indication.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q70, PDF p.487; answer on PDF p.500","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":70,"f":false},{"id":"NEL-CNSACCEPTE-074","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"A slowly progressive ataxia that involves the lower extremities to a greater degree than the upper extremities. The Romberg test result is positive; the deep-tendon reflexes are absent (particularly at the ankle), and the plantar response is typically extensor (Babinski sign). Of the following, the MOsT likely cause of this ataxia is","o":["ataxia-telangiectasia","Friedreich ataxia","abetalipoproteinemia","Roussy-Levy disease","Ramsay Hunt syndrome"],"k":1,"ex":"Friedreich ataxia is autosomal recessive, with onset before age 10, slowly progressive ataxia worse in the legs, positive Romberg sign, absent ankle reflexes, extensor plantar response, dysarthria and nystagmus.","more":"Options:\n- A. ataxia-telangiectasia — earlier onset, with telangiectasia and immunodeficiency.\n\n- B. **Correct (source key).**\n- C. abetalipoproteinemia — ataxia with fat malabsorption and acanthocytes.\n- D. Roussy-Levy disease — hereditary neuropathy with tremor.\n- E. Ramsay Hunt syndrome — not a fit for this picture.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q74, PDF p.488; answer on PDF p.500","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":74,"f":false},{"id":"NEL-CNSACCEPTE-076","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pathophysiology","q":"Prematurity is a major cause of","o":["spastic diplegia","spastic quadriplegia","spastic hemiplegia","athetoid CP","dyskinetic CP"],"k":0,"ex":"Prematurity (periventricular injury), ischemia, infection and endocrine/metabolic causes are major causes of spastic diplegia.","more":"Options:\n- A. **Correct (source key).**\n\n- B. spastic quadriplegia — more linked to severe diffuse injury.\n- C. spastic hemiplegia — perinatal stroke.\n- D. athetoid CP — kernicterus or basal ganglia injury.\n- E. dyskinetic CP — same as D.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q76, PDF pp.488-489; answer on PDF p.501","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":76,"f":false},{"id":"NEL-CNSACCEPTE-077","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The MOsT severe form of CP is","o":["spastic diplegia","spastic quadriplegia","spastic hemiplegia","athetoid CP","dyskinetic CP"],"k":1,"ex":"Spastic quadriplegia is the most severe form of cerebral palsy: all four limbs are markedly impaired and it is highly associated with intellectual disability and seizures.","more":"Options:\n- A. spastic diplegia — less severe.\n\n- B. **Correct (source key).**\n- C. spastic hemiplegia — less severe.\n- D. athetoid CP — variable.\n- E. dyskinetic CP — variable.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q77, PDF p.489; answer on PDF p.501","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":77,"f":false},{"id":"NEL-CNSACCEPTE-078","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"All the following can be used for treatment of cerebral palsy (CP) ExCEPT","o":["benzodiazepines","baclofen","dantrolene","botulinum toxin","hyperbaric oxygen"],"k":4,"ex":"Hyperbaric oxygen has not been shown to improve the condition of children with cerebral palsy. Benzodiazepines, baclofen, dantrolene and botulinum toxin are used for spasticity.","more":"Options:\n- A. benzodiazepines — used.\n\n- B. baclofen — used.\n- C. dantrolene — used.\n- D. botulinum toxin — used.\n- E. **Correct (source key).**","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q78, PDF p.489; answer on PDF p.501","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":78,"f":false},{"id":"NEL-CNSACCEPTE-093","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"Data support the use of intravenous dexamethasone, 0.15 mg/kg/dose given every 6 hr for 2 days, in the treatment of children older than 6 wk with acute bacterial meningitis caused by H. influenza type b. for the following reasons EXCEPT","o":["shorter duration of fever","lower CSF protein","lower mortality","lower CSF lactate levels","reduction in sensorineural hearing loss"],"k":2,"ex":"Dexamethasone in Hib meningitis shortens fever, lowers CSF protein and lactate and reduces sensorineural hearing loss, but a lower mortality has not been shown. Benefit for other bacteria is inconclusive.","more":"Options:\n- A. shorter duration of fever — shown.\n\n- B. lower CSF protein — shown.\n- C. **Correct (source key).**\n- D. lower CSF lactate — shown.\n- E. reduced sensorineural hearing loss — shown.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q93, PDF pp.491-492; answer on PDF p.502","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":93,"f":false},{"id":"NEL-CNSACCEPTE-095","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Complications","q":"The MosT common neurologic sequelae of bacterial meningitis is","o":["recurrent seizures","delay in acquisition of language","hearing loss","cognitive impairment","visual impairment"],"k":2,"ex":"Sensorineural hearing loss is the commonest sequela of bacterial meningitis (up to 30% pneumococcal, 10% meningococcal, 5-20% Hib), usually present at diagnosis, and all patients need audiologic assessment.","more":"Options:\n- A. recurrent seizures — less common.\n\n- B. language delay — less common.\n- C. **Correct (source key).**\n- D. cognitive impairment — less common.\n- E. visual impairment — less common.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q95, PDF p.492; answer on PDF p.502","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":95,"f":false},{"id":"NEL-CNSACCEPTE-096","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The MosT common cause of viral meningoencephalitis are","o":["arboviruses 1","enteroviruses","herpes simplex virus (HSV) type 1","varicella-zoster virus","mumps"],"k":1,"ex":"Enteroviruses are the commonest cause of viral meningoencephalitis (more than 70 serotypes).","more":"Options:\n- A. arboviruses — less common.\n\n- B. **Correct (source key).**\n- C. HSV-1 — encephalitis, less common.\n- D. varicella-zoster virus — less common.\n- E. mumps — less common (vaccine era).","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q96, PDF p.492; answer on PDF p.502","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":96,"f":false},{"id":"NEL-CNSACCEPTE-099","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The predominant organisms causing brain abscesses in chtioren are","o":["aerobic and anaerobic streptococci","Streptococcus pneumoniae","Enterococcus faecalis","bacteroides spp","Haemophilus aphrophilus"],"k":0,"ex":"Aerobic and anaerobic streptococci (60-70%), notably the Streptococcus milleri group, are the predominant organisms in pediatric brain abscesses.","more":"Options:\n- A. **Correct (source key).**\n\n- B. Streptococcus pneumoniae — less common.\n- C. Enterococcus faecalis — less common.\n- D. Bacteroides spp. — part of the anaerobic flora but not predominant alone.\n- E. Haemophilus aphrophilus — rare.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q99, PDF p.493; answer on PDF p.502","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":99,"f":false},{"id":"NEL-CNSACCEPTE-001","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The skull tends to assume a square or boxlike shape in","o":["Kleinfelter syndrome","neurofibromatosis","storage disorder","chronic subdural hemorrhages","hydrocephalus"],"k":3,"ex":"In chronic subdural hemorrhage the long-standing fluid in the subdural space enlarges the middle fossa, so the skull takes a square or boxlike shape (source explanation).","more":"Options:\n- A. Klinefelter syndrome — no characteristic skull-shape change.\n\n- B. neurofibromatosis — may cause macrocephaly, not the boxlike shape in the source.\n- C. storage disorder — coarse features and macrocephaly, not the boxlike shape.\n- D. **Correct (source key).**\n- E. hydrocephalus — head enlargement with frontal bossing, not the boxlike shape.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q1, PDF p.475; answer on PDF p.495","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":1,"f":false},{"id":"NEL-CNSACCEPTE-002","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other","q":"Smell can be tested reliably at","o":["32nd wk of gestation","birth","three months of age",". six months of age","nine months of age"],"k":0,"ex":"Smell can be tested reliably from the 32nd week of gestation by presenting an appropriate stimulus (coffee, peppermint) and watching for an alerting response or withdrawal. Strong irritants such as ammonia must be avoided because they stimulate the trigeminal nerve.","more":"Options:\n- A. **Correct (source key):** 32nd week of gestation.\n\n- B-E. Birth, 3, 6 and 9 months — later ages than the source states; smell is already testable earlier.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q2, PDF p.475; answer on PDF p.495","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":2,"f":false},{"id":"NEL-CNSACCEPTE-005","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"Xanthochromia of cerebrospinal fluid (CSF) suggests the following ExCEPT","o":["bloody tap","subarachnoid hemorrhage","carotenemia","hyperbilirubinemia","markedly elevated CSF protein"],"k":0,"ex":"Xanthochromia (yellow CSF from hemoglobin breakdown) suggests subarachnoid hemorrhage (after about 12 hours) and occurs with hyperbilirubinemia, carotenemia and markedly raised CSF protein. In a bloody (traumatic) tap, the CSF clears progressively and the supernatant is clear after centrifugation, so a bloody tap is the exception.","more":"Options:\n- A. **Correct (source key):** a bloody tap gives a clear supernatant.\n\n- B. subarachnoid hemorrhage — causes xanthochromia.\n- C. carotenemia — causes xanthochromia.\n- D. hyperbilirubinemia — causes xanthochromia.\n- E. markedly elevated CSF protein — causes xanthochromia (label lost in OCR).\n\nHigh-yield:\nXanthochromia may be absent in bleeds less than 12 hours old.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q5, PDF pp.475-476; answer on PDF p.495","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":5,"f":false},{"id":"NEL-CNSACCEPTE-009","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Mobius syndrome is characterized by the following EXCEPT","o":["bilateral facial weakness","paralysis of the abducens nerve","hypoplasia or agenesis of brainstem nuclei","feeding difficulties","mental retardation"],"k":4,"ex":"Möbius syndrome is congenital facial and abducens palsy from hypoplasia or agenesis of brainstem nuclei, with feeding difficulty from facial weakness. The immobile, dull face can falsely suggest intellectual disability, but development is normal in most (source explanation), so intellectual disability is the exception.","more":"Options:\n- A. bilateral facial weakness — characteristic.\n\n- B. paralysis of the abducens nerve — characteristic (label lost in OCR).\n- C. hypoplasia or agenesis of brainstem nuclei — characteristic.\n- D. feeding difficulties — characteristic.\n- E. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q9, PDF p.476; answer on PDF p.495","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":9,"f":false},{"id":"NEL-CNSACCEPTE-014","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pathophysiology","q":"Regarding the CSF, all the following are true EXCEPT","o":["approximately 25% of CSF originates from extrachoroidal sources","in a normal child, about 20 mL/hr of CSF is produced","total volume of CSF approximates 150 mL in an infant","normally, CSF flows from the lateral ventricles through the foramina of Monro into the 3rd ventricle","CSF is absorbed primarily by the arachnoid villi"],"k":2,"ex":"The CSF volume is about 50 mL in an infant and 150 mL in an adult (source explanation), so the statement of 150 mL in an infant is false. About 70-75% of CSF comes from the choroid plexus (the rest is extrachoroidal), production is about 20 mL/hr, flow runs from the lateral ventricles through the foramina of Monro, and absorption is mainly by the arachnoid villi.","more":"Options:\n- A. about 25% extrachoroidal — true.\n\n- B. 20 mL/hr production — true.\n- C. **Correct (source key).**\n- D. flow through the foramina of Monro — true (label lost in OCR).\n- E. absorbed by the arachnoid villi — true.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q14, PDF p.477; answer on PDF p.496","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":14,"f":false},{"id":"NEL-CNSACCEPTE-019","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Differential Diagnosis","q":"Dravet syndrome is characterized by all the following EXCEPT","o":["the most severe of the phenotypic spectrum of febrile seizures","its onset is in the 1st yr of life","seizures subsequently start to occur without fever","developmental delay","an autosomal dominant inheritance"],"k":4,"ex":"Dravet syndrome (severe myoclonic epilepsy of infancy) begins in the first year, usually with fever-related prolonged seizures, followed by afebrile seizures and developmental delay. It is the most severe end of the SCN1A spectrum that includes GEFS+.","more":"Options:\n- A. most severe phenotype of the febrile seizure spectrum — true.\n\n- B. onset in the first year — true.\n- C. later seizures without fever — true.\n- D. developmental delay — true.\n- E. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q19, PDF p.478; answer on PDF p.496","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":19,"f":false},{"id":"NEL-CNSACCEPTE-024","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pharmacology","q":"Rickets is a potential side effect from all the following ExcEPT","o":["phenytoin","valproate","phenobarbital","primidone","carbamazepine"],"k":1,"ex":"Rickets can result from enzyme-inducing antiepileptics (phenytoin, phenobarbital, primidone, carbamazepine), which reduce 25-hydroxy-vitamin D by increasing its metabolism. Valproate does not do this; its characteristic effect is hyperammonemia.","more":"Options:\n- A. phenytoin — enzyme inducer, causes rickets.\n\n- B. **Correct (source key).**\n- C. phenobarbital — enzyme inducer.\n- D. primidone — enzyme inducer.\n- E. carbamazepine — enzyme inducer.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q24, PDF p.479; answer on PDF p.496","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":24,"f":false},{"id":"NEL-CNSACCEPTE-027","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pharmacology","q":"All the following are true regarding diazepam in neonatal seizures ExCEPT","o":["diazepam is highly lipophilic",". it is cleared very quickly","recurrence of seizures is more than other anticonvulsants","it carries a risk of apnea and hypotension","it is currently recommended as a first-line agent"],"k":4,"ex":"Diazepam is not recommended as a first-line drug for neonatal seizures. It is highly lipophilic and quickly redistributed, so seizure recurrence is more frequent than with other anticonvulsants; it risks apnea and hypotension; and the IV preparation contains sodium benzoate and benzoic acid.","more":"Options:\n- A. highly lipophilic — true.\n\n- B. cleared very quickly — true (label lost in OCR).\n- C. higher recurrence than other drugs — true.\n- D. risk of apnea and hypotension — true.\n- E. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q27, PDF pp.479-480; answer on PDF p.497","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":27,"f":false},{"id":"NEL-CNSACCEPTE-033","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"3 All the following are features of Von Hippel-Lindau (VHL) disease EXCEPT","o":["its incidence is around 1: 36,000","fifty percent have a de novo gene mutation","hemangioblastoma of the spinal cord may be found","renal carcinoma is the most common cause of death","pheochromocytoma is a frequent association"],"k":1,"ex":"In von Hippel-Lindau disease about 80% of patients have an affected parent and about 20% a de novo mutation, so 'fifty percent de novo' is false. Spinal and cerebellar hemangioblastoma, renal cell carcinoma (the commonest cause of death) and pheochromocytoma are recognized features.","more":"Options:\n- A. incidence around 1:36,000 — true.\n\n- B. **Correct (source key).**\n- C. spinal cord hemangioblastoma — true.\n- D. renal carcinoma most common cause of death — true.\n- E. pheochromocytoma — true.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q33, PDF pp.480-481; answer on PDF p.497","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":33,"f":false},{"id":"NEL-CNSACCEPTE-034","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"PHACE syndrome denotes to the following EXCEPT","o":["posterior fossa malformations","hemangiomas","anal anomalies","coarctation of the aorta","eye abnormalities"],"k":2,"ex":"PHACE stands for Posterior fossa malformations, large facial Hemangiomas, Arterial anomalies, Cardiac anomalies (such as coarctation of the aorta) and Eye abnormalities. 'Anal anomalies' is not part of it.","more":"Options:\n- A. posterior fossa malformations — P.\n\n- B. hemangiomas — H.\n- C. **Correct (source key):** the 'A' stands for arterial, not anal.\n- D. coarctation of the aorta — cardiac anomaly (C).\n- E. eye abnormalities — E.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q34, PDF p.481; answer on PDF p.497","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":34,"f":false},{"id":"NEL-CNSACCEPTE-039","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other","q":"How often are EEGs abnormal in healthy children?","o":["5%","10%","15%","20%","25%"],"k":1,"ex":"About 10% of 'normal' children have mild, nonspecific background abnormalities on EEG, so an isolated nonspecific abnormality should not be over-interpreted.","more":"Options:\n- A. 5% — too low.\n\n- B. **Correct (source key).**\n- C. 15%.\n- D. 20%.\n- E. 25%.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q39, PDF p.482; answer on PDF p.498","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":39,"f":false},{"id":"NEL-CNSACCEPTE-040","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other (Epidemiology)","q":"The MosT common precipitant of status epilepticus in children is","o":["CNS infection","fever","medication change","trauma","metabolic cause"],"k":1,"ex":"The most common precipitant of status epilepticus in children is fever/infection (36%), followed by medication change (20%), unknown (9%), metabolic (8%), congenital (7%), CNS infection and anoxia (5% each), trauma (4%), cerebrovascular (3%), alcohol/drugs (2%) and tumor (1%).","more":"Options:\n- A. CNS infection — 5%.\n\n- B. **Correct (source key).**\n- C. medication change — 20%.\n- D. trauma — 4%.\n- E. metabolic cause — 8%.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q40, PDF p.482; answer on PDF p.498","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":40,"f":false},{"id":"NEL-CNSACCEPTE-042","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other (Development)","q":"A premature infant blinks in response to a bright light at","o":["26 wk of corrected gestational age","28 wk of corrected gestational age","30 wk of corrected gestational age","32 wk of corrected gestational age","34 wk of corrected gestational age"],"k":1,"ex":"A premature infant blinks to bright light at 28 weeks of corrected gestational age and holds eye closure until the light is removed at 32 weeks; a 37-week infant turns toward a soft light and a term infant fixes on and follows a target.","more":"Options:\n- A. 26 wk — earlier than the source.\n\n- B. **Correct (source key).**\n- C. 30 wk — later.\n- D. 32 wk — eye closure maintained.\n- E. 34 wk — later.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q42, PDF p.482; answer on PDF p.498","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":42,"f":false},{"id":"NEL-CNSACCEPTE-043","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The MOsT common cause of anatomic megalencephaly is","o":["Sotos syndrome","benign familial megalencephaly","Simpson-Golabi-Behmel syndrome","fragile X syndrome","Weaver syndrome"],"k":1,"ex":"Benign familial megalencephaly is the most common cause of anatomic megalencephaly; overgrowth syndromes such as Sotos, Simpson-Golabi-Behmel, fragile X and Weaver are less common causes.","more":"Options:\n- A. Sotos syndrome — overgrowth syndrome.\n\n- B. **Correct (source key).**\n- C. Simpson-Golabi-Behmel syndrome — overgrowth syndrome.\n- D. fragile X syndrome — less common.\n- E. Weaver syndrome — overgrowth syndrome.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q43, PDF p.482; answer on PDF p.498","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":43,"f":false},{"id":"NEL-CNSACCEPTE-048","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The majority of patients who had prolonged febrile seizures and encephalopathy after vaccination and who had been presumed to have suffered from vaccine encephalopathy (seizures and psychomotor regression occurring after vaccination and presumed to be caused by it) turn out to have","o":["generalized epilepsy with febrile seizures plus(GEFS+)","temporal lobe epilepsy secondary to mesial temporal sclerosis","myoclonic astatic seizures","Dravet syndrome","focal febrile seizures plus epilepsy variant"],"k":3,"ex":"Most infants thought to have 'vaccine encephalopathy' (prolonged febrile seizures and regression after vaccination) turn out to carry Dravet syndrome (SCN1A) mutations, so the disease is caused by the mutation and not by the vaccine.","more":"Options:\n- A. GEFS+ — milder SCN1A spectrum.\n\n- B. temporal lobe epilepsy with mesial sclerosis — not the finding.\n- C. myoclonic astatic epilepsy — not the finding.\n- D. **Correct (source key).**\n- E. focal febrile seizures plus variant — not the finding.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q48, PDF p.483; answer on PDF p.498","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":48,"f":false},{"id":"NEL-CNSACCEPTE-049","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Prognosis","q":"Higher risk of recurrence of the febrile seizure is associated with lower serum","o":["sodium","potassium","chloride","calcium","magnesium"],"k":0,"ex":"A lower serum sodium is associated with a higher risk of recurrence of febrile seizure within the following 24 hours.","more":"Options:\n- A. **Correct (source key).**\n\n- B. potassium, C. chloride, D. calcium, E. magnesium — not linked to recurrence risk in the source.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q49, PDF p.483; answer on PDF p.499","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":49,"f":false},{"id":"NEL-CNSACCEPTE-054","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"The ketogenic diet is absolutely contraindicated in","o":["primary carnitine deficiency","myoclonic- astatic epilepsy","tuberous sclerosis complex","Rett syndrome","infantile spasms"],"k":0,"ex":"The ketogenic diet is absolutely contraindicated in primary carnitine deficiency and in other fatty-acid oxidation defects, pyruvate carboxylase deficiency and porphyrias. It is used in myoclonic-astatic epilepsy, tuberous sclerosis, Rett syndrome and infantile spasms.","more":"Options:\n- A. **Correct (source key).**\n\n- B. myoclonic-astatic epilepsy — indication.\n- C. tuberous sclerosis complex — indication.\n- D. Rett syndrome — indication.\n- E. infantile spasms — indication.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q54, PDF p.484; answer on PDF p.499","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":54,"f":false},{"id":"NEL-CNSACCEPTE-056","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Prognosis","q":"The following factors are associated with a higher risk of seizure relapse after antiepileptic drugs (AEDs) withdrawal EXCEPT","o":["younger age of epilepsy onset","longer duration of epilepsy","presence of multiple seizure types","need to use more than 1 AED","abnormal EEG before medication is discontinued"],"k":0,"ex":"Factors linked to relapse after stopping antiepileptic drugs include older age at epilepsy onset, longer duration of epilepsy, multiple seizure types, need for more than one drug and abnormal EEG. Younger age at onset is the exception (source explanation).","more":"Options:\n- A. **Correct (source key).**\n\n- B. longer duration — raises relapse risk.\n- C. multiple seizure types — raises relapse risk.\n- D. need for more than 1 AED — raises relapse risk.\n- E. abnormal EEG before withdrawal — raises relapse risk.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q56, PDF p.485; answer on PDF p.499","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":56,"f":false},{"id":"NEL-CNSACCEPTE-057","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Prognosis","q":"Sudden unexpected death in epilepsy (SUDEP) is the most common epilepsy related mortality in patients with chronic epilepsy. All the following are risk factors ExCEPT","o":["polypharmacology","female gender","age younger than 16 yr","long duration of epilepsy","frequent seizures"],"k":1,"ex":"Risk factors for SUDEP include polytherapy, young age, long duration of epilepsy, frequent seizures and male gender (source). Female gender is the exception.","more":"Options:\n- A. polypharmacology — risk factor.\n\n- B. **Correct (source key).**\n- C. age younger than 16 yr — risk factor.\n- D. long duration of epilepsy — risk factor.\n- E. frequent seizures — risk factor.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q57, PDF p.485; answer on PDF p.499","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":57,"f":false},{"id":"NEL-CNSACCEPTE-058","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pathophysiology","q":"There are 5 main neonatal seizure types: subtle, clonic, tonic, spasms, and myoclonic. One of the following seizures is frequently not associated with electrographic discharges","o":["spasms","focal clonic","subtle","focal tonic","generalized myoclonic"],"k":2,"ex":"Of the neonatal seizure types, subtle seizures (and motor automatisms, generalized tonic and multifocal myoclonic episodes) are frequently not associated with EEG discharges and are thought to be release phenomena from brain injury. Spasms, focal clonic, focal tonic and generalized myoclonic seizures are usually associated with electrographic discharges.","more":"Options:\n- A. spasms — EEG discharges.\n\n- B. focal clonic — EEG discharges.\n- C. **Correct (source key).**\n- D. focal tonic — EEG discharges.\n- E. generalized myoclonic — EEG discharges.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q58, PDF p.485; answer on PDF p.499","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":58,"f":false},{"id":"NEL-CNSACCEPTE-059","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Subtle seizures include all the following ExcEPT","o":["blinking","mouthing","fluctuations in heart rate","hypotension episodes","apnea"],"k":3,"ex":"Subtle seizures include eye deviations, nystagmus, blinking, mouthing, limb pedaling/rowing movements, heart-rate fluctuations, episodes of hypertension and apnea; they are more common in preterm infants. Hypotension episodes are not listed (hypertension is).","more":"Options:\n- A. blinking — listed.\n\n- B. mouthing — listed.\n- C. fluctuations in heart rate — listed (label lost in OCR).\n- D. **Correct (source key):** the source lists hypertension, not hypotension.\n- E. apnea — listed.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q59, PDF p.485; answer on PDF p.499","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":59,"f":false},{"id":"NEL-CNSACCEPTE-060","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The following are features of Aicardi syndrome ExCEPT","o":["coloboma of the iris","retinal lacunae","agenesis of the corpus callosum","severe seizures","aminoaciduria"],"k":4,"ex":"Aicardi syndrome affects girls only and consists of retinal lacunae, agenesis of the corpus callosum and severe seizures including infantile spasms with hypsarrhythmia. Aminoaciduria is not a feature.","more":"Options:\n- A. coloboma of the iris — ocular malformation recognized in the syndrome.\n\n- B. retinal lacunae — characteristic.\n- C. agenesis of the corpus callosum — characteristic.\n- D. severe seizures — characteristic.\n- E. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q60, PDF pp.485-486; answer on PDF p.499","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":60,"f":false},{"id":"NEL-CNSACCEPTE-063","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pharmacology","q":"intravenous phenytoin is not widely used to control acute neonatal seizures because of all the following EXCEPT","o":["reduced solubility","severe local cutaneous reactions","interaction with other drugs","possible cardiac toxicity","not possible to mix with saline solutions"],"k":4,"ex":"IV phenytoin is not widely used for neonatal seizures because of poor solubility, severe local skin reactions on extravasation, drug interactions and possible cardiac toxicity. Phenytoin cannot be mixed with dextrose solutions (the source explanation), whereas saline is the usual diluent, so the statement that it cannot be mixed with saline is the incorrect reason.","more":"Options:\n- A. reduced solubility — valid reason.\n\n- B. severe local cutaneous reactions — valid reason.\n- C. interaction with other drugs — valid reason.\n- D. possible cardiac toxicity — valid reason.\n- E. **Correct (source key):** the incompatibility is with dextrose, not saline.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q63, PDF p.486; answer on PDF p.500","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":63,"f":false},{"id":"NEL-CNSACCEPTE-069","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The aura associated with migraine is a neurologic warning that a migraine is going to occur. Of the following, the LEAsT common type of typical auras is","o":["sensory aura","dysphasic aura","visual aura","vertigo","distortion"],"k":1,"ex":"Typical auras are visual, sensory and dysphasic; dysphasic auras are the least common. Atypical auras are hemiplegic and 'Alice in Wonderland' phenomena.","more":"Options:\n- A. sensory aura — typical, more common.\n\n- B. **Correct (source key).**\n- C. visual aura — the commonest.\n- D. vertigo — not listed among typical auras in the source.\n- E. distortion — not listed among typical auras in the source.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q69, PDF p.487; answer on PDF p.500","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":69,"f":false},{"id":"NEL-CNSACCEPTE-071","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Differential Diagnosis","q":"Café-au-lait macules are not specific for NF-1; they may be seen in the following EXCEPT","o":["Noonan syndrome","ataxia telangiectasia","Fanconi anemia","Gaucher disease","Hurler syndrome"],"k":4,"ex":"Café-au-lait macules are not specific for NF-1 and also occur in Noonan syndrome, ataxia-telangiectasia, Fanconi anemia and Gaucher disease. Mucopolysaccharidoses are not associated.","more":"Options:\n- A. Noonan syndrome — can have café-au-lait macules.\n\n- B. ataxia-telangiectasia — can.\n- C. Fanconi anemia — can.\n- D. Gaucher disease — can.\n- E. **Correct (source key):** a mucopolysaccharidosis.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q71, PDF pp.487-488; answer on PDF p.500","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":71,"f":false},{"id":"NEL-CNSACCEPTE-073","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other","q":"Slow, writhing, continuous, and involuntary movements are called","o":["stereotypies","tics","tremor","athetosis","chorea"],"k":3,"ex":"Athetosis is slow, writhing, continuous involuntary movement. Chorea is brief, irregular and flowing; tics are sudden stereotyped movements; tremor is rhythmic oscillation; stereotypies are repetitive patterned movements.","more":"Options:\n- A. stereotypies — repetitive patterned movements.\n\n- B. tics — sudden brief stereotyped.\n- C. tremor — rhythmic.\n- D. **Correct (source key).**\n- E. chorea — brief, irregular.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q73, PDF p.488; answer on PDF p.500","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":73,"f":false},{"id":"NEL-CNSACCEPTE-075","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The MosT common acquired cause of chorea in childhood is","o":["Huntington disease","paraneoplastic choreas","benign hereditary chorea","Sydenham chorea","chorea gravidarum"],"k":3,"ex":"Sydenham chorea is the most common acquired chorea of childhood, occurring in 10-20% of acute rheumatic fever patients weeks to months after group A streptococcal infection, peaking at 8-9 years with a 2:1 female predominance.","more":"Options:\n- A. Huntington disease — rare in children.\n\n- B. paraneoplastic chorea — rare.\n- C. benign hereditary chorea — genetic, not acquired.\n- D. **Correct (source key).**\n- E. chorea gravidarum — during pregnancy.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q75, PDF p.488; answer on PDF p.501","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":75,"f":false},{"id":"NEL-CNSACCEPTE-079","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Infants with Tay-Sachs disease (TSD) are characterized by the following ExCEPT","o":["convulsions","blindness","deafness","cherry-red spots","microcephaly"],"k":4,"ex":"Tay-Sachs disease (hexosaminidase A deficiency, GM2 ganglioside storage) causes regression, convulsions, blindness, hyperacusis then deafness and a cherry-red macular spot, with macrocephaly (not microcephaly) by 1 year from the stored ganglioside.","more":"Options:\n- A. convulsions — feature.\n\n- B. blindness — feature.\n- C. deafness — feature.\n- D. cherry-red spots — feature.\n- E. **Correct (source key):** macrocephaly occurs.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q79, PDF p.489; answer on PDF p.501","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":79,"f":false},{"id":"NEL-CNSACCEPTE-080","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Excessive irritability and crying, unexplained episodes of hyperpyrexia, vomiting, and difficulty feeding are the symptoms of the following neuro-degenerative disease","o":["Tay-Sachs disease (TsD)","Sandhoff disease","juvenile GM2 gangliosidosis","Krabbe disease (KD)","metachromatic leukodystrophy"],"k":3,"ex":"Krabbe disease (globoid cell leukodystrophy) presents in the first months with excessive irritability and crying, unexplained hyperpyrexia, vomiting and feeding difficulty, often treated as colic or milk allergy.","more":"Options:\n- A. Tay-Sachs — regression, cherry-red spot.\n\n- B. Sandhoff disease — GM2, like Tay-Sachs plus organomegaly.\n- C. juvenile GM2 gangliosidosis — later onset.\n- D. **Correct (source key).**\n- E. metachromatic leukodystrophy — later onset gait problems.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q80, PDF p.489; answer on PDF p.501","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":80,"f":false},{"id":"NEL-CNSACCEPTE-081","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Presenting symptoms in pediatric multiple sclerosis (MS) include the following EXCEPT","o":["hemiparesis","optic neuritis","ataxia","dysarthria","encephalopathy"],"k":4,"ex":"Pediatric MS presents with hemiparesis, optic neuritis, ataxia and dysarthria; encephalopathy is less common and suggests ADEM or neuromyelitis optica.","more":"Options:\n- A. hemiparesis — common.\n\n- B. optic neuritis — common.\n- C. ataxia — common.\n- D. dysarthria — common.\n- E. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q81, PDF p.489; answer on PDF p.501","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":81,"f":false},{"id":"NEL-CNSACCEPTE-084","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Bilateral cortical visual dysfunction, encephalopathy, and seizures are seen in","o":["global hypoxic-ischemic encephalopathy","herpes encephalitis","multiple sclerosis","hypertensive encephalopathy","hypoglycemia"],"k":3,"ex":"Posterior reversible encephalopathy syndrome (PRES) occurs with hypertension, often an acute rise in blood pressure; the posterior regions are selectively involved, giving bilateral cortical visual dysfunction, encephalopathy and seizures.","more":"Options:\n- A. global hypoxic-ischemic encephalopathy — diffuse injury.\n\n- B. herpes encephalitis — temporal lobe involvement.\n- C. multiple sclerosis — demyelination.\n- D. **Correct (source key).**\n- E. hypoglycemia — can affect occipital regions but is not the keyed answer.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q84, PDF p.490; answer on PDF p.501","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":84,"f":false},{"id":"NEL-CNSACCEPTE-085","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"The imaging studies are usually normal in the following stroke-like disorders of children","o":["alternating hemiplegia","inborn errors of metabolism","hypertensive encephalopathy","hypoglycemia","global hypoxic-ischemic encephalopathy"],"k":0,"ex":"Imaging is usually normal in alternating hemiplegia of childhood, which is diagnosed clinically; in the other stroke-like disorders MRI usually shows abnormalities.","more":"Options:\n- A. **Correct (source key).**\n\n- B. inborn errors of metabolism — MRI abnormalities are common.\n- C. hypertensive encephalopathy — MRI shows posterior changes.\n- D. hypoglycemia — can show occipital changes.\n- E. global HIE — shows injury patterns.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q85, PDF p.490; answer on PDF p.501","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":85,"f":false},{"id":"NEL-CNSACCEPTE-086","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"8 Small vessel childhood primary angitis of the CNS (SVcPACNS) is usually presented with","o":["arterial ischemic stroke","seizures","cognitive dysfunction","personality changes","loss of social control"],"k":1,"ex":"More than 80% of children with small-vessel childhood primary angiitis of the CNS present with seizures, and all seizure types are seen.","more":"Options:\n- A. arterial ischemic stroke — not the commonest presentation here.\n\n- B. **Correct (source key).**\n- C. cognitive dysfunction — less common.\n- D. personality changes — less common.\n- E. loss of social control — less common.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q86, PDF p.490; answer on PDF p.501","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":86,"f":false},{"id":"NEL-CNSACCEPTE-088","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"The organism causing CNS infection is never seen on direct examination of CSF in","o":["tuberculous meningitis","acute bacterial meningitis","partially treated bacterial meningitis","fungal meningitis","amebic (naegleria) meningoencephalitis"],"k":0,"ex":"In tuberculous meningitis acid-fast organisms are almost never seen on direct CSF smear; they may be recovered from culture of large volumes and detected by PCR.","more":"Options:\n- A. **Correct (source key).**\n\n- B. acute bacterial meningitis — organisms usually seen on Gram stain.\n- C. partially treated bacterial meningitis — often seen.\n- D. fungal meningitis — may be seen (India ink).\n- E. amebic meningoencephalitis — organisms can be seen on wet mount.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q88, PDF p.491; answer on PDF p.501","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":88,"f":false},{"id":"NEL-CNSACCEPTE-089","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Pathophysiology","q":"T-lymphocyte defects (congenital or acquired by chemotherapy, AlDs, or malignancy) are associated with an increased risk of infections of the CNS with","o":["Listeria monocytogenes","Streptococcus pneumoniae","Neisseria meningitidis","Haemophilus influenzae type b","coagulase-negative Staphylococci"],"k":0,"ex":"T-lymphocyte defects increase the risk of CNS infection with Listeria monocytogenes, an intracellular organism controlled by cell-mediated immunity.","more":"Options:\n- A. **Correct (source key).**\n\n- B-E. capsulated bacteria and coagulase-negative staphylococci — linked to antibody/complement defects, shunts and neonatal infection, not T-cell defects.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q89, PDF p.491; answer on PDF p.501","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":89,"f":false},{"id":"NEL-CNSACCEPTE-090","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Other","q":"The CsF leukocyte count in normal healthy neonates may reach","o":["10 leukocytes/mm3","15 leukocytes/mm3","20 leukocytes/mm3","25 leukocytes/mm3","30 leukocytes/mm3"],"k":4,"ex":"Normal healthy neonates may have as many as 30 leukocytes/mm3 in the CSF (usually under 10), whereas older children without meningitis have fewer than 5; lymphocytes or monocytes predominate in both.","more":"Options:\n- A-D. 10, 15, 20, 25 — below the stated maximum.\n\n- E. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q90, PDF p.491; answer on PDF p.501","nlSourceKey":"E","nlChapter":"Central Nervous System","nlNumber":90,"f":false},{"id":"NEL-CNSACCEPTE-091","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Treatment","q":"The following is an alternative treatment for L. monocytogenes meningitis","o":["vancomycin","cefotaxime","chloramphenicol","intravenous trimethoprimsulfamethoxazole","meropenem"],"k":3,"ex":"For suspected Listeria monocytogenes meningitis, ampicillin is given because cephalosporins are inactive; intravenous trimethoprim-sulfamethoxazole is the alternative named by the source.","more":"Options:\n- A. vancomycin — not named.\n\n- B. cefotaxime — inactive against Listeria.\n- C. chloramphenicol — not named.\n- D. **Correct (source key).**\n- E. meropenem — has activity against Listeria and appears as an alternative in some guidelines, but is not the source's alternative.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q91, PDF p.491; answer on PDF p.502","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":91,"f":false},{"id":"NEL-CNSACCEPTE-092","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Complications","q":"Reversible gallbladder pseudolithiasis, detectable by abdominal ultrasonography during treatment of bacterial meningitis is usually caused by","o":["ceftazidime","cefotaxime","ceftriaxone","meropenem","chloramphenicol"],"k":2,"ex":"Ceftriaxone can cause reversible gallbladder pseudolithiasis (biliary sludge, detectable on ultrasound), usually asymptomatic but sometimes with vomiting and right upper quadrant pain.","more":"Options:\n- A. ceftazidime, B. cefotaxime, D. meropenem, E. chloramphenicol — not linked.\n\n- C. **Correct (source key).**","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q92, PDF p.491; answer on PDF p.502","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":92,"f":false},{"id":"NEL-CNSACCEPTE-100","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A brain abscess can be treated with antibiotics without surgery in the following conditions EXCEPT","o":["abscess is <2 cm in diameter","illness is of short duration (<2 wk)","lesion is located in the posterior fossa","no signs of increased intracranial pressure","child is neurologically intact"],"k":2,"ex":"A small abscess can be treated medically if it is under about 2.5 cm, the illness is short, there is no raised ICP and the child is neurologically intact. A posterior fossa location, gas, multiloculation, fungus or a large size are indications for surgery.","more":"Options:\n- A. small abscess — medical therapy possible.\n\n- B. short duration — medical therapy possible.\n- C. **Correct (source key):** posterior fossa is an indication for surgery.\n- D. no signs of raised ICP — medical therapy possible.\n- E. neurologically intact — medical therapy possible.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q100, PDF p.493; answer on PDF p.502","nlSourceKey":"C","nlChapter":"Central Nervous System","nlNumber":100,"f":false},{"id":"NEL-CNSACCEPTE-101","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Idiopathic intracranial hypertension, also known as pseudotumor cerebri, is a clinical syndrome that mimics brain tumors and is characterized by the following EXCEPT","o":["increased intracranial pressure ≥280 mm Hg in nonobese, nonsedated children","normal cerebrospinal fluid (CsF) cell count and protein content","normal to slightly decreased ventricular size","normal ventricular anatomy and position documented by MRI","papilledema"],"k":0,"ex":"In idiopathic intracranial hypertension the opening pressure is at least 280 mm of water in sedated or obese children and at least 250 in nonobese, nonsedated children; the CSF cell count and protein are normal, ventricular size is normal or slightly small and papilledema is present. The option quoting 280 for nonobese, nonsedated children is therefore the exception.","more":"Options:\n- A. **Correct (source key).**\n\n- B. normal CSF cells and protein — true.\n- C. normal to small ventricles — true.\n- D. normal ventricular anatomy on MRI — true.\n- E. papilledema — true.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q101, PDF p.493; answer on PDF p.503","nlSourceKey":"A","nlChapter":"Central Nervous System","nlNumber":101,"f":false},{"id":"NEL-CNSACCEPTE-102","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Differential Diagnosis","q":"The following are hematologic causes of childhood pseudotumor cerebri ExcEpT","o":["Wiskott-Aldrich syndrome","megaloblastic anemia","polycythemia","sickle cell disease","Fanconi anemia"],"k":1,"ex":"Hematologic causes of pseudotumor cerebri include iron-deficiency anemia, polycythemia, sickle cell disease and related disorders. Megaloblastic anemia is the exception per the key (the source lists iron-deficiency anemia).","more":"Options:\n- A. Wiskott-Aldrich syndrome — listed in the stem as a cause.\n\n- B. **Correct (source key).**\n- C. polycythemia — cause.\n- D. sickle cell disease — cause.\n- E. Fanconi anemia — cause.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q102, PDF p.493; answer on PDF p.503","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":102,"f":false},{"id":"NEL-CNSACCEPTE-103","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The MosT common presenting complaint of intramedullary spinal cord tumors is","o":["gait disturbance",". sensory deficits","scoliosis","back pain *'t","urinary urgency"],"k":3,"ex":"Intramedullary spinal cord tumors usually present insidiously; back pain at the tumor level is the commonest complaint, often waking the child at night and easing during the day.","more":"Options:\n- A. gait disturbance — later.\n\n- B. sensory deficits — later (label lost in OCR).\n- C. scoliosis — later.\n- D. **Correct (source key).**\n- E. urinary urgency — later.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q103, PDF pp.493-494; answer on PDF p.503","nlSourceKey":"D","nlChapter":"Central Nervous System","nlNumber":103,"f":false},{"id":"NEL-CNSACCEPTE-104","spec":"cns","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":". The MosT common involved segments in transverse myelitis (TM) are in the","o":["cervical region","thoracic region","lumbar region","lumbo-sacral region","sacral region"],"k":1,"ex":"Transverse myelitis most often involves the thoracic cord segments.","more":"Options:\n- A. cervical region — less common.\n\n- B. **Correct (source key).**\n- C. lumbar, D. lumbo-sacral, E. sacral — less common.","nl":true,"nlClass":"Extended Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs Q104, PDF pp.494-495; answer on PDF p.503","nlSourceKey":"B","nlChapter":"Central Nervous System","nlNumber":104,"f":false},{"id":"NEL-DERMATOLOG-002","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The diagnosis of allergic rhinitis is established by the time the child reaches age of","o":["2yr","4yr","6yr","8yr","10 yr"],"k":2,"ex":"Allergic rhinitis may start in infancy but is usually recognised by about 6 years; prevalence peaks late in childhood.","more":"Nelson explanation:\n2.(C). The symptoms may appear in Infancy; with the diagnosis generally established by\nthe time the child reaches age 6 yr. The prevalence peaks late in chlldhood.\n\nOptions:\nA/B too early (rare before 3 y); D/E later than the usual recognition age.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 206 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":2,"f":false},{"id":"NEL-DERMATOLOG-014","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The percentage of allergic rhinitis in asthmatic patients is 78%, while the percentage of asthma in patients with allergic rhinitis is","o":["18%","28%","38%","48%","58%"],"k":2,"ex":"Asthma and allergic rhinitis coexist (one airway disease): most asthmatics have rhinitis, fewer rhinitis patients have asthma.","more":"Nelson explanation:\n14.(C).\n\nOptions:\nNumeric recall; only C (38%) matches Nelson. Curriculum gives only 'up to 80% of asthmatics have rhinitis'.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 208 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":14,"f":false},{"id":"NEL-DERMATOLOG-015","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"To avoid false-negative skin test results in atopic host, most sedating antihistamine should be withheld for 3-4 days, and nonsedating antihistamines for 5-7 days, while montelukast should be withheld for","o":["1 day","3 day","5 day","7 day","9 day"],"k":0,"ex":"Drugs that block histamine response suppress skin-prick tests, so they are stopped before testing. Montelukast does not block the wheal much, so the washout is short.","more":"Nelson explanation:\n15.(A).\n\nOptions:\nOptions are only washout durations (1–9 days); key A per Nelson.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Key per Nelson only; low-yield detail, cannot verify independently","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 208 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":15,"f":true},{"id":"NEL-DERMATOLOG-016","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The best method for detection of allergen-specific IgE is","o":["skin tests","serum immune assay for specific IgE","nasal smear study eosinophilia in blood film 198 [Continuation on source page 209]","total serum IgE concentration"],"k":0,"ex":"Skin-prick (epicutaneous) testing is the most sensitive, cheap and quick way to show allergen-specific IgE.","more":"Nelson explanation:\n16.(A). Epicutaneous skin tests provide the best method for detection of allergen-\nspecific igE (positive predictive value of 48.7% for the epidemiologic diagnosis of AR).\nThey are inexpensive and sensitive, and the risks and discomfort are minimal.\n\nOptions:\nB serum specific IgE = alternative (costly, less sensitive); nasal/blood eosinophilia and total IgE are non-specific. OCR merged options C/D.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ OCR: options C and D merged in the stem","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 208 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":16,"f":true},{"id":"NEL-DERMATOLOG-018","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"The MOsT effective therapy for persistent allergic rhinitis is","o":["oral desloratadine","oral montelukast","subcutaneous omalizumab","nasal budesonide spray","nasal ipratropium bromide spray"],"k":3,"ex":"Intranasal corticosteroid (budesonide) is the most effective drug for persistent allergic rhinitis.","more":"Nelson explanation:\n18.(D). Patients with more persistent, severe symptoms require intranasal\ncorticosteroids, the most effective therapy for allergic rhinitls, a treatment that may be\nbeneficial also for concomitant allergic conjunctivitis.\n\nOptions:\nA/B oral antihistamine or montelukast are less effective; C omalizumab is for refractory cases; E ipratropium only helps rhinorrhoea.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 209 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":18,"f":false},{"id":"NEL-DERMATOLOG-019","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Approximately 80% of all asthmatic patients report disease onset prior to the age of A2yr","o":["4yr","6yr","8yr","10 yr"],"k":2,"ex":"About 80% of asthmatics have symptoms before 6 years, which is why early-life risk factors matter.","more":"Nelson explanation:\n19.(C).\n218\n[Source page 229]\nF:\n\nOptions:\nRecall of an age cutoff; C (6 yr) per Nelson.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 209 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":19,"f":false},{"id":"NEL-DERMATOLOG-020","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Of the following, the major risk factor for persistent asthma is","o":["eczema","allergic rhinitis","wheezing apart from colds","food allergen sensitization","z4% peripheral blood eosinophils"],"k":0,"ex":"Early risk factors for persistent asthma are grouped as major (parental asthma, eczema, inhalant sensitisation) and minor (rhinitis, non-cold wheeze, eosinophils ≥4%, food sensitisation).","more":"Nelson explanation:\n20.(A). Early childhood risk factors for persistent asthma have been identified and have\nbeen described as major (parent asthma, eczema, inhalant allergen sensitization) and\np\nminor (allergic rhinitis, wheezing apart from colds, ≥4% peripheral blood eosinophils,\nfood allergen sensitization) risk factors.\n\nOptions:\nOnly A (eczema) is major; B–E are all minor factors.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 209 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":20,"f":false},{"id":"NEL-DERMATOLOG-021","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Of the following, the strongest identifiable factor for the persistence of childhood asthma is","o":["allergy","male gender","low birth weight","parental asthma","lower respiratory tract infection"],"k":0,"ex":"Atopy/allergic sensitisation is the strongest identifiable predictor of persistence.","more":"Nelson explanation:\n21.(A).\n\nOptions:\nD (parental asthma) is also a strong predictor and is listed as major in Q20, so two answers are defensible.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Possible two defensible answers (A vs D); Nelson explanation missing → move to Needs Review","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 209 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":21,"f":true},{"id":"NEL-DERMATOLOG-023","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Recurrent coughing and wheezing occurs In 35% of preschool-age children. Those who continue to have persistent asthma Into later chlldhood are approximately","o":["one-fifth","one-fourth","one-third","one-half","two-thirds"],"k":2,"ex":"About one third of preschool wheezers go on to persistent asthma; two thirds improve by their teens.","more":"Nelson explanation:\n23.(C). Of these, approximately one-third who continue to have persistent asthma into\nlater childhood, and approximately two-thirds improve on their own through their teen\nyears.\n\nOptions:\nFractions only; C (one-third) per Nelson.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 210 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":23,"f":false},{"id":"NEL-DERMATOLOG-024","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Indications of severe exacerbation of asthma Include the following ExCEPT","o":["breathlessness","accessory muscles use","labored breath","PEF or FEV1 value <70% of personal best values","mental status changes"],"k":3,"ex":"Severe exacerbation = marked breathlessness, accessory muscle use, altered mental status and PEF/FEV1 below 50% of best.","more":"Nelson explanation:\n24.(D). Severe airflow limitation (PEF or FEV1 value <50% of personal best or predicted\n5\nvalues).\n\nOptions:\nA,B,C,E are severe signs. D (<70%) is too mild: the severe cut-off is <50%.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 210 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":24,"f":false},{"id":"NEL-DERMATOLOG-028","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"All the following are considered as risk factors for asthma morbidity and mortality EXCEPT","o":["poverty","air pollution exposure","female gender","poor response to systemic steroid therapy","sudden asphyxia episodes"],"k":2,"ex":"Poverty, pollution, sudden asphyxia and poor steroid response worsen asthma outcomes; male gender (not female) is the risk factor.","more":"Nelson explanation:\n28.(C). Male gender.\n\nOptions:\nC is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 211 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":28,"f":false},{"id":"NEL-DERMATOLOG-029","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"The best \"rescue\" medication in the treatment of acute asthma symptoms is","o":["oral SABA","inhaled SABA","oral corticosteroid","inhaled ipratropium","inhaled corticosteroid"],"k":1,"ex":"Inhaled short-acting β2-agonist is the first rescue drug, up to 3 doses in the first hour.","more":"Nelson explanation:\n29.(B). Inhaled SABA, up to 3 treatments in 1 hr. If the child has an incomplete\nresponse to initial treatment with rescue medication (persistent symptoms and/or a\nPEF value <80% of personal best), a short course of oral corticosteroid therapy\n(prednisone 1-2 mg/kg/day [not to exceed 60 mg/day] for 4 days), in addition to\ninhaled β-agonist therapy, should be instituted.\n\nOptions:\nA oral SABA is slower; C steroid is added if response is incomplete; D ipratropium is adjunct in severe attacks; E ICS is controller, not rescue.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 211 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":29,"f":false},{"id":"NEL-DERMATOLOG-030","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"The best treatment option for step -6- severe persistent asthma in a 6-year-old boy is","o":["medium dose inhaled corticosteroids with long acting B-agonists","high dose inhaled corticosteroids with leukotriene receptor antagonist","low dose inhaled corticosteroids with leukotriene receptor antagonist","high dose inhaled corticosteroids with long acting B-agonist and oral corticosteroids","high dose inhaled corticosteroids with long acting B-agonist and oral corticosteroidsalong with omalizumab therapy"],"k":3,"ex":"Step 6 (severe persistent) uses high-dose ICS + LABA + oral corticosteroid; omalizumab is an add-on in allergic asthma.","more":"Nelson explanation:\n30.(D).\n\nOptions:\nA–C are lower steps. D and E both fit step 6; E only adds omalizumab.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Guideline-dependent; D vs E defensible → consider Needs Review","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 211 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":30,"f":true},{"id":"NEL-DERMATOLOG-031","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"A common finding of chest radiograph in a child with asthma is","o":["peribronchial thickening","atelectasis","pneumothorax","bronchiectasis","pneumomediastinum"],"k":0,"ex":"Chest X-ray in asthma shows hyperinflation, flattened diaphragm and peribronchial thickening; complications are rare.","more":"Nelson explanation:\n31.(A). Peribronchial thickening and flattening of diaphragm.\n\nOptions:\nB–E are complications seen only occasionally.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 211 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":31,"f":false},{"id":"NEL-DERMATOLOG-035","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"All the following are a recognized features of a \"well-controlled\" asthma in a 7- year-old boy EXCEPT","o":["FEV1:FVC ratio >80%","FEV1of >80% of predicted","daytime symptoms ≤2 days/wk","z4 exacerbations in the past year","need a rescue bronchodilator ≤2 days/wk"],"k":3,"ex":"Well-controlled asthma means symptoms and rescue use ≤2 days/week, normal activity, FEV1 >80% and fewer than 2 exacerbations/year.","more":"Nelson explanation:\n35.(D). Children with well-controlled asthma have daytime symptoms ≤2 days/wk and\nneed a rescue bronchodilator ≤2 days/wk; an FEV1of >80% of predicted (and an FEV1:\nFVC ratio >80% for children 5-11 yr of age); no interference with normal activity; and <2\nexacerbations in the past year.\n\nOptions:\nD (≥4 exacerbations) contradicts control; the others are control criteria.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 212 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":35,"f":false},{"id":"NEL-DERMATOLOG-038","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Adverse effects of frequently administered β-agonist therapy in asthma include all the following EXCEPT","o":["tremor","irritability","tachycardia","hypokalemia","mouth dryness"],"k":4,"ex":"β2-agonists cause tremor, tachycardia, irritability and hypokalaemia; dry mouth is an anticholinergic effect.","more":"Nelson explanation:\n38.(E).\n219\n[Source page 230]\nr\n\nOptions:\nA–D are classic β2 effects; E is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"✔ Key plausible; Nelson explanation is OCR page marker only","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 213 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":38,"f":true},{"id":"NEL-DERMATOLOG-039","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Atopic dermatitis affects many children worldwide, the exact percentage approximating","o":["5-10%","10-30%","30-50%","50-70%","70-90%"],"k":1,"ex":"Atopic dermatitis is common: roughly 10–30% of children (curriculum ≈20%).","more":"Nelson explanation:\n39.(B).\n\nOptions:\nOnly B (10–30%) fits.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 213 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":39,"f":false},{"id":"NEL-DERMATOLOG-040","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The hallmark of atopic dermatitis is","o":["intense pruritus","cutaneous reactivity","lichenification .fibrotic papules","dry skin"],"k":null,"ex":"Nelson calls dry skin (epidermal barrier defect) the hallmark, while pruritus is the cardinal symptom (see Q42).","more":"Nelson explanation:\n40.(E). The hallmark of atopic dermatitis is dry skin, is results from compromise of the\nepidermal barrier, which leads to excess transepidermal water loss, allergen\npenetration, and microbial colonization.\n\nOptions:\nA pruritus is the cardinal feature, not the hallmark; B–D are secondary findings.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Depends on Nelson wording; overlaps Q42\nThe OCR question text/options or source key are incomplete; the answer is disabled until checked.","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 213 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":40,"f":true,"kx":true},{"id":"NEL-DERMATOLOG-041","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Atopic dermatitis typically begins in","o":["infancy","toddlerhood","preschooler age","school age","adolescence"],"k":0,"ex":"Onset is typically in infancy (≈50% in the first year, uncommon in the first 2 months).","more":"Nelson explanation:\n41.(A). Approximately 50% of patients experience symptoms in the 1st yr of life, and an\nadditional 30% are diagnosed between 1 and 5 yr of age.\n\nOptions:\nB–E are later onset ages.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 213 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":41,"f":false}]);